begin;
set local standard_conforming_strings=on;
do $guard$ begin if (select count(*) from public.books b cross join lateral jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') r where b.id='anna-karenina' and r->>'id'='regional-pokrovskoe')<>1 then raise exception 'Missing model record';end if;end $guard$;
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-pokrovskoe' then jsonb_set(r,'{place}',((r->'place')-'regionalOutline')||'{"name":"Pokrovskoye · model: Yasnaya Polyana","area":"Yasnaya Polyana","coords":[54.076147,37.526311],"kind":"uncertain","zoom":15,"checked":"2026-10-19","status":"Documented real literary inspiration","note":"The point locates Yasnaya Polyana, the documented real inspiration for Levin’s fictional Pokrovskoye. It does not identify the fictional estate or assign real addresses to its buildings.","method":"The point identifies the real model. It does not reconstruct fictional streets, buildings, distances or routes.","positionSource":{"url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates?SingleLine=Yasnaya+Polyana+Museum%2C+Russia&f=json&outFields=Match_addr%2CAddr_type&maxLocations=3","label":"ArcGIS · Yasnaya Polyana · verified real model"},"additionalSource":{"url":"https://ypmuseum.ru/event/1283","label":"Yasnaya Polyana Museum · Pokrovskoye and Yasnaya Polyana"},"geographicReview":{"precision":"literary-model","realWorldIdentity":"verified-real-inspiration","reason":"The point locates Yasnaya Polyana, the documented real inspiration for Levin’s fictional Pokrovskoye. It does not identify the fictional estate or assign real addresses to its buildings."},"scope":"real-literary-model"}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') with ordinality a(r,ord))) where b.id='anna-karenina';
do $guard$ begin if (select count(*) from public.books b cross join lateral jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') r where b.id='sound-and-fury' and r->>'id'='regional-jefferson')<>1 then raise exception 'Missing model record';end if;end $guard$;
update public.books b set metadata=jsonb_set(b.metadata,'{geographicReview,regionalPlaces}',(select jsonb_agg(case when r->>'id'='regional-jefferson' then jsonb_set(r,'{place}',((r->'place')-'regionalOutline')||'{"name":"Jefferson · model: Oxford, Mississippi","area":"Oxford, Mississippi","coords":[34.3668,-89.518625],"kind":"uncertain","zoom":12,"checked":"2026-10-19","status":"Documented real literary inspiration","note":"The point locates Oxford, Mississippi, the documented real inspiration for fictional Jefferson. The two towns are distinct in Faulkner’s fiction. No Oxford building or address is identified with a fictional Jefferson setting.","method":"The point identifies the real model. It does not reconstruct fictional streets, buildings, distances or routes.","positionSource":{"url":"https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates?SingleLine=Oxford%2C+Mississippi%2C+USA&f=json&outFields=Match_addr%2CAddr_type&maxLocations=1","label":"ArcGIS · Oxford, Mississippi · verified real model"},"additionalSource":{"url":"https://faulkner.iath.virginia.edu/shanti/content/oxford-mississippi","label":"University of Virginia · Digital Yoknapatawpha · Oxford and Jefferson"},"geographicReview":{"precision":"literary-model","realWorldIdentity":"verified-real-inspiration","reason":"The point locates Oxford, Mississippi, the documented real inspiration for fictional Jefferson. The two towns are distinct in Faulkner’s fiction. No Oxford building or address is identified with a fictional Jefferson setting."},"scope":"real-literary-model"}'::jsonb) else r end order by ord) from jsonb_array_elements(b.metadata#>'{geographicReview,regionalPlaces}') with ordinality a(r,ord))) where b.id='sound-and-fury';
on conflict(book_id,language,source_hash) do update set translated_text=excluded.translated_text;
commit;select id,r->>'id' as place_id,r#>>'{place,name}' as model,r#>'{place,coords}' as coords,r#>'{place,regionalOutline}' is null as point_without_outline from public.books cross join lateral jsonb_array_elements(metadata#>'{geographicReview,regionalPlaces}') r where (id='anna-karenina' and r->>'id'='regional-pokrovskoe') or (id='sound-and-fury' and r->>'id'='regional-jefferson');